  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C15", "C17", "C07", "C13", "C18", "C27", "C06", "C08", "C23", "C24"],
  "claims": [
    {
      "claim": "Bumetanide, a sulfonamide loop diuretic structurally closest to the query, had absolute oral bioavailability of 95% in patients with cirrhosis (1 mg oral vs IV, n=8), with a second record reporting 95-100%; this is the strongest same-condition, same-class transfer.",
      "card_ids": ["C03", "C15", "C17"]
    },
    {
      "claim": "Tolfenamic acid in cirrhosis showed absolute oral bioavailability of about 100% by AUC comparison after 100 mg p.o. vs i.v., with additional patient values of 91%, 113%, and 126%, all far above the 20% threshold.",
      "card_ids": ["C07", "C13", "C18", "C27"]
    },
    {
      "claim": "Isradipine in cirrhosis had systemic availability of about 37% (36.9 ± 16.2%), and a reanalysis reported a mean of 0.28 in cirrhotic patients without shunts; the mean values remain above 20%.",
      "card_ids": ["C06", "C08", "C23", "C24"]
    },
    {
      "claim": "The query physicochemical prior (neutral fraction 0, logD -0.84, TPSA 100) is not affirmative evidence of F below 20%; acidic, ionized drugs such as bumetanide and tolfenamic acid show high F in the same cirrhosis condition.",
      "card_ids": ["C03", "C15", "C07", "C13"]
    },
    {
      "claim": "New L5 gut-wall efflux and intestinal-metabolism records concern unrelated molecules (isoniazid, DF2755A, compound 2, compound 19, dapivirine) and are mostly repeated Caco-2 permeability measurements; none measures the query or a cirrhosis condition, so they do not alter the prediction.",
      "card_ids": ["C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63"]
    }
  ],
  "evidence_gaps": [
    "No direct torasemide-in-cirrhosis bioavailability or AUC record is present in the supplied cards.",
    "L5 records are Caco-2 efflux/permeability measurements for other molecules only; none reports F for the query or for cirrhosis.",
    "Query-specific gut-wall efflux, intestinal metabolism, solubility, and first-pass extraction are not experimentally measured; the low prior is physicochemical only.",
    "Cirrhosis severity and the query dose and formulation are unspecified; transfer from bumetanide, tolfenamic acid, and isradipine relies on structural and condition analogy.",
    "Some low-F records in the broader set (KNI-272 syrup, IQG-607 in mice, slow-dissolving isoniazid tablet) involve different molecules, species, or formulations and cannot be quantitatively transferred."
  ],
  "decision_summary": "Predicted high (F >= 20%): all transferable cirrhosis-context records, bumetanide 95-100%, tolfenamic acid about 100% (91-126%), and isradipine 28-37%, are above threshold. New L5 gut-wall efflux and intestinal-metabolism records are not absolute F measurements and concern unrelated molecules, so they do not change the decision. The physicochemical low prior is not affirmative evidence of F below 20%. Confidence remains high; revision kept."
}

